import {hpSchoolLife,hpTradeLife,hpSpellRows} from './world_packs/book_hp_life_data.js';
import {hpLeadLife} from './world_packs/book_hp_lead_life_data.js';
import {getHpLeadCast} from './book_world_hp_lead_pack.js';
import {hpLeadFlightFacts} from './book_world_hp_lead_flight.js';
import {hpLeadDuelFacts} from './book_world_hp_lead_duel.js';
import {hpLeadHalloweenFacts} from './book_world_hp_lead_halloween.js';
import {hpLeadQuidditchFacts} from './book_world_hp_lead_quidditch.js';
import {hpLeadMirrorFacts} from './book_world_hp_lead_mirror.js';
import {hpLeadFlamelFacts} from './book_world_hp_lead_flamel.js';
import {hpLeadNorbertFacts} from './book_world_hp_lead_norbert.js';
import {hpLeadFinaleFacts} from './book_world_hp_lead_finale.js';
// HP-local clock projection. Shared simulation owns all elapsed time, jobs and skill settlement.
import {recurringWindow} from './world_rhythm.js';
import {hpLessonFacts} from './book_world_hp_lessons.js';
import {hpExamFacts} from './book_world_hp_exams.js';
import {hpLeadSpellFacts} from './hp_lead_spells.js';
import {hpCharmRows} from './read_models/hp_charm_bridge.js';
export function hpSchoolCalendar(state){
 const P='book.hp.school',opening=state.simulation?.knowledge?.player?.[P+'.opening'];
 if(state.actors?.player?.worldId!==P+'.world'||!opening)return null;
 const elapsed=Math.max(0,state.clock-opening.at),day=Math.floor((elapsed+540)/1440),minute=(elapsed+540)%1440;
 const teaching=day<70&&day%7<5;
 return {day:day+1,minute,hour:Math.floor(minute/60),teaching,
  label:`Term day ${day+1} · ${String(Math.floor(minute/60)).padStart(2,'0')}:${String(minute%60).padStart(2,'0')} · ${day>=70?'term break':day%7>=5?'weekend':'teaching day'}`,
  charms:teaching&&recurringWindow({period:1440,opens:540,closes:660},elapsed+540).open,
  plants:teaching&&recurringWindow({period:1440,opens:780,closes:900},elapsed+540).open};
}
export function hpFacts(state,context={}){
 const world=state.actors?.player?.worldId,trade=world==='book.hp.trade.world',c=hpSchoolCalendar(state);
 // The lead life's day index (anchor 08:00 on day 0), for gates such as the 1 September arrival; the profile's own arithmetic.
 if(world==='book.hp.lead.world'){const opening=state.simulation?.knowledge?.player?.['book.hp.lead.opening'];
  return opening?{'hp.lead.day':Math.floor((Math.max(0,state.clock-opening.at)+480)/1440),...hpLessonFacts(state,context),...hpExamFacts(state,context),...hpLeadSpellFacts(state),...hpLeadFlightFacts(context),...hpLeadDuelFacts(context),...hpLeadHalloweenFacts(context),...hpLeadQuidditchFacts(context),...hpLeadMirrorFacts(context),...hpLeadFlamelFacts(context),...hpLeadNorbertFacts(context),...hpLeadFinaleFacts(context)}:{};}
 if(trade)return {'hp.trade.wandReady':(context.gameplay?.player?.inventory?.[JSON.stringify({id:'book.hp.trade.wand'})]||0)>0};
 if(!c)return {};
 const inv=context.gameplay?.player?.inventory||{},P='book.hp.school',held=n=>(inv[JSON.stringify({id:P+'.'+n})]||0)>0;
 return {'structured.extension.book.hp.school.assessed_repair.admitted':!!context.structuredNative?.extensions?.some(e=>e.id==='book.hp.school.assessed_repair'&&e.revision===1),
  'hp.school.assessmentStart':c.charms&&c.minute+10<660,
  'hp.school.wandReady':held('wand')||held('practice_wand'),'hp.school.charmsOpen':c.charms,'hp.school.plantsOpen':c.plants,
  'hp.school.charmsStart':c.charms&&c.minute+30<660,'hp.school.plantsStart':c.plants&&c.minute+30<900};
}

export function hpLifeStatus(state,context={}){
 const P=state.actors?.player?.worldId?.replace(/\.world$/,''),a=state.actors?.player;
 if(!['book.hp.school','book.hp.trade'].includes(P))return [];
 const r=a.resources,unit=P.endsWith('school')?'allowance':'coins';
 const rows=[{label:'Current local means',value:`${r[P+'.'+unit]||0} local units · ${r[P+'.debt']||0} debt units`}];
 if(P.endsWith('trade'))rows.push({label:'Counter till',value:`${state.actors[P+'.merchant']?.resources[P+'.coins']||0} trade units`});
 const assessment=state.simulation.knowledge.player?.['book.hp.school.assessed_repair.passed'],contribution=state.simulation.knowledge.player?.['book.hp.school.assessed_repair.contributed'];
 if(assessment&&P.endsWith('school'))rows.push({label:'Assessed repair',value:assessment.value});
 if(contribution&&P.endsWith('school'))rows.push({label:'Classroom contribution',value:contribution.value});
 const inv=context.gameplay?.player?.inventory||{},count=n=>inv[JSON.stringify({id:P+'.'+n})]||0;
 if(P.endsWith('trade'))rows.push({label:'Owned stock',value:`${count('glass_shards')} complete fragment sets · ${count('glass_pane')} repaired panes`});
 if(P.endsWith('school'))rows.push(...hpCharmRows(state,hpSchoolCalendar(state),hpSpellRows));
 else for(const [id,p]of Object.entries(state.simulation.powers.player||{}))if(id.startsWith(P+'.'))rows.push({label:'Glass repair',value:`${p.owned?'learned':'not learned'} · ${p.mastery} practice steps · ${p.executions} executions`});
 return rows;
}

export function hpCalendarBinding(state){
 const life=[hpSchoolLife,hpTradeLife,hpLeadLife].find(l=>state?.actors?.player?.worldId===l.world.id);
 const opening=life&&state.simulation?.knowledge?.player?.[life.id+'.opening'];
 const instance=life&&state.worlds?.[life.world.id]?.facts?.[life.id+'.instance'];
 // The opening has a stated Saturday. In the source school route, the
 // weekday from the household clock would conflict with the stated scenes.
 if(!opening||!instance)return null;
 const school=life===hpLeadLife&&getHpLeadCast()?.schoolWeek&&state.actors.player.facts['hp.lead.atSchool'];
 const profile=life===hpLeadLife?{...life.calendarProfile,showWeekday:!school,...(school?{label:'School days'}:{})}:life.calendarProfile;
 return {profile,instanceId:instance,elapsed:Math.max(0,state.clock-opening.at)};
}
