        const next=JSON.stringify([s,frame.context,frame.ready,frame.writable,frame.automaticReady]);if(next===signature&&!force)return;signature=next;const active=panel.contains(document.activeElement)?document.activeElement:null;const focus=active?{specimen:active.dataset.harvestSpecimen,choice:active.dataset.harvestChoice,action:active.dataset.harvest}:null;body.replaceChildren();
        const text=document.createElement('p');text.style.margin='6px 0';text.textContent=`Keep up to ${HARVEST_CAP} per species. Choose a specific carcass before processing. Age follows played time and changes quality; strike damage changes how complete each part is. One-part processing yields only that part; the other parts are lost. Hands take twice as long. Freshness declines over four played hours. ${s.left} carcasses left behind at capacity.`;body.append(text);
