        const cycles=document.createElement('p');cycles.dataset.harvestCycles='';cycles.textContent=`${s.processed} carcasses processed in this save. ${s.auto?'Continuing automatically while eligible; uncheck to finish the current carcass and stop.':'Automatic processing is off; any current carcass finishes before stopping.'}`;body.append(cycles);
