import {registerDomain} from './domain_registry.js';
import {computeAway} from './away_ledger.js';
import {formatDuration} from './number_format.js';
// OD4/TBANK/AD18 time bank. Real time between the last save and this load is banked as game
// minutes at the native awake cadence (one per tick, like the Patient Furnace). Nothing is applied
// on return: the player spends the bank through the native clock, so every cost, body need and
// choice stop applies and no time-free reward is granted (AD16, AD38).
// Spending counts minutes on the root clock (a sleeping tick covers several), so a spend of n moves the clock n minutes,
// plus at most one tick's span when a tick straddles the end; the debit is what the clock consumed (TMR5, TMR11).
// Dials (proposals, not accepted numbers): capacity 7 days, drop beyond it, 60 minutes per spend.
// Capacity is the AD18 improvement hook: ports.capacity() may return a larger value.
// Compatibility: a save without the slice starts at an empty bank with lastSeen = now, so old
// saves never receive a retroactive bank. The last-seen time is the save's own `saved_at` stamp (local
// time, second precision), so the slice holds no wall time and the durable writer's unchanged-bytes
// dedupe (D3) and byte-equal save tests keep working. Every save restamps it, so played time never banks.
// Patient Furnace rule: while its routine is assigned it accrues the same wall time itself, so
// this ledger only rebases and does not also credit it.
export const AWAY_BANK_DEFAULTS=Object.freeze({capacity:7*24*60,spendMinutes:60,minReport:1});
// TMR6 (RCL6): the one bank's cap starts at 7 days and grows through registered sources (play, cheats, research,
// items: BT6). Each source returns extra minutes and states its reason; the projection lists them. The first source is
// play itself. Proposal dial: one more day of capacity per 30 played days. Uncapped stays a dial (a source may return
// Infinity). Other banks draw from this one at their own efficiency (the Mistglass practice) or rebase on it (the Furnace).
const capacitySources=new Map();
export function registerAwayCapacity(id,source){
    if(typeof id!=='string'||!id||typeof source?.minutes!=='function'||typeof source.reason!=='string')throw new Error('Invalid away capacity source.');
    if(capacitySources.has(id))throw new Error(`Away capacity source ${id} is already registered.`);
    capacitySources.set(id,source);
}
export const AWAY_GROWTH_PLAY=Object.freeze({playedMinutesPerDay:30*24*60,
    reason:'Every 30 days you have played, the bank keeps one more day of unused time.'}); // proposal dial (TMR6)
registerAwayCapacity('play',{minutes:root=>Math.floor((root?.clock??0)/AWAY_GROWTH_PLAY.playedMinutesPerDay)*24*60,reason:AWAY_GROWTH_PLAY.reason});
function capacityParts(){
    const root=ports?.root?.();
    return [...capacitySources].map(([id,s])=>{const n=s.minutes(root);return {id,minutes:Number.isFinite(n)||n===Infinity?Math.max(0,n):0,reason:s.reason};}).filter(p=>p.minutes>0);
}
const natural=n=>Number.isSafeInteger(n)&&n>=0;
let ports=null,state=null,pending=null,busy=false,lastSpend='';
export function configureAwayBank(operations){ports=operations;}
const now=()=>ports?.now?.()??Date.now();
const capacity=()=>Math.max(AWAY_BANK_DEFAULTS.capacity+capacityParts().reduce((n,p)=>n+p.minutes,0),ports?.capacity?.()??0);
export function savedAtMs(stamp){
    const m=/^(\d{4})-(\d{2})-(\d{2}) (\d{2})_(\d{2})_(\d{2})$/.exec(stamp??'');
    return m?new Date(+m[1],+m[2]-1,+m[3],+m[4],+m[5],+m[6]).getTime():NaN;
}
export function validateAwayBank(slice){
    if(slice==null)return slice;
    if(typeof slice!=='object'||Array.isArray(slice)||Object.keys(slice).sort().join(',')!=='bankedMinutes,remainderMs,schema'||slice.schema!==1||
        !natural(slice.bankedMinutes)||!natural(slice.remainderMs)||slice.remainderMs>=60000)throw new Error('Invalid away bank.');
    return slice;
}
// Credits the wall time since the load once the other domains (cheats) exist. Idempotent.
function settle(){
    if(!pending||!state)return;
    const {lastSeen,at}=pending;pending=null;
    if(ports?.furnaceAssigned?.()){state.lastSeen=at;state.remainderMs=0;return;}
    const r=computeAway({lastSeen,now:at,capMinutes:0,overflow:'bank',bankedMinutes:state.bankedMinutes,remainderMs:state.remainderMs});
    const banked=Math.min(capacity(),r.bankedMinutes),gained=Math.max(0,banked-state.bankedMinutes);
    state.bankedMinutes=banked;state.remainderMs=r.stoppedBy==='clock-back'?0:r.remainderMs;state.lastSeen=at;
    if(r.overflowMinutes>=AWAY_BANK_DEFAULTS.minReport)state.lastReturn={minutes:r.overflowMinutes,banked:gained,dropped:r.overflowMinutes-gained};
}
// The balance another bank may draw from (TMR6), and the debit after its own plan saved.
export function awayBankBalance(){settle();return state?state.bankedMinutes:0;}
export function takeAwayBank(minutes){
    settle();
    if(!state)throw new Error('The game is still loading.');
    const n=Math.min(Math.max(0,Math.floor(minutes)),state.bankedMinutes);
    if(n>0){state.bankedMinutes-=n;ports?.persist?.(()=>{});}
    return n;
}
export async function spendAwayBank(minutes=AWAY_BANK_DEFAULTS.spendMinutes){
    settle();
    if(!ports||!state)throw new Error('The game is still loading.');
    if(busy)throw new Error('Banked time is already being spent.');
    if(ports.writable?.()===false)throw new Error('Saving is unavailable, so banked time cannot be spent.');
    const n=Math.min(Math.floor(minutes),state.bankedMinutes);
    if(!(n>=1))throw new Error('No time is banked.');
    const root=ports.root(),before=root.clock;
    busy=true;
    try{await ports.fastForward(n,{untilClock:before+n});}finally{busy=false;}
    const consumed=Math.max(0,ports.root().clock-before);
    state.bankedMinutes=Math.max(0,state.bankedMinutes-consumed);
    lastSpend=consumed<n?`Stopped after ${formatDuration(consumed)} of ${formatDuration(n)}, at a choice that waits for you; the rest stays banked.`:`Spent ${formatDuration(consumed)} of banked time.`;
    ports.persist(()=>{});
    return {requested:n,consumed};
}
export const awayBankDomain=registerDomain({id:'awayBank',initialState:()=>null,
    save:()=>{if(!state)return undefined;settle();return {schema:1,bankedMinutes:state.bankedMinutes,remainderMs:state.remainderMs};},
    validate:slice=>{validateAwayBank(slice);},
    load:(slice,envelope)=>{
        validateAwayBank(slice);const at=now(),seen=savedAtMs(envelope?.saved_at);
        state={lastSeen:at,bankedMinutes:slice?.bankedMinutes??0,remainderMs:slice?.remainderMs??0,lastReturn:null};
        pending=slice&&Number.isFinite(seen)?{lastSeen:seen,at}:null;lastSpend='';
    },
    projection:()=>{
        if(!state)return null;settle();
        return {bankedMinutes:state.bankedMinutes,capacity:capacity(),capacitySources:capacityParts(),lastReturn:state.lastReturn,lastSpend,spendMinutes:Math.min(AWAY_BANK_DEFAULTS.spendMinutes,state.bankedMinutes),
            busy,writable:ports?.writable?.()!==false};
    },
    commands:{spend:spendAwayBank}});
