import {definePanel} from './panel_kit.js';
export function createDrainagePanel({read,act}){
 const n=(tag,text)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;return e;},root=n('section');root.id='drainage_site_panel';root.className='expedition_panel';const body=n('div'),notice=n('p');notice.setAttribute('role','status');root.append(n('h2','Riverside exploration'),body,notice);let signature='';
 const render=()=>{if(!root.isConnected)return;const v=read(),sig=JSON.stringify(v);if(sig===signature)return;signature=sig;body.replaceChildren(n('p',v.description));if(!v.visible)return;
  body.append(n('p','Original Frontier site. Native travel owns your position and travel time. Inspect observed passages before working; actual carried wood, rope, fuel, stamina and surveyed footing support different methods. Search costs and fumble risk rise as the face loosens. A fumble loses one chunk into the drain and causes a small nonlethal strain; withdrawal uses the ordinary return route. Absence creates no new search or replacement stock.'));
  if(v.map.nodes.length){const caption=n('p',`Own onsite sketch · edition ${v.map.edition} · ${v.map.world} · ${v.map.frame}. Marks record your observations, with no title or claim to the site.`);body.append(caption);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'),nodes=v.map.nodes,xs=nodes.map(r=>r.x),ys=nodes.map(r=>r.y),minX=Math.min(...xs),minY=Math.min(...ys);svg.setAttribute('viewBox',`${minX*70-35} ${minY*70-35} ${(Math.max(...xs)-minX+1)*70} ${(Math.max(...ys)-minY+1)*70}`);svg.style.width='100%';svg.style.maxHeight='260px';svg.setAttribute('role','img');svg.setAttribute('aria-label','Your observed drainage passages');
   const make=(tag,attrs)=>{const e=document.createElementNS(svg.namespaceURI,tag);for(const [k,val]of Object.entries(attrs))e.setAttribute(k,String(val));svg.append(e);return e;};for(const [a,b]of v.map.edges){const from=nodes.find(r=>r.id===a),to=nodes.find(r=>r.id===b);make('line',{x1:from.x*70,y1:from.y*70,x2:to.x*70,y2:to.y*70,stroke:'currentColor','stroke-width':2});}for(const r of nodes){make('circle',{cx:r.x*70,cy:r.y*70,r:17,fill:r.id===v.room?'var(--ui-teal)':'var(--ui-navy)',stroke:r.inspected?'var(--ui-accent)':'var(--ui-hairline)','stroke-width':2});const t=make('text',{x:r.x*70,y:r.y*70+5,fill:'var(--ui-text)','text-anchor':'middle','font-size':14});t.textContent=String(r.id+1);}body.append(svg);for(const r of nodes)body.append(n('p',`Marker ${r.id+1}: ${r.inspected?'inspected':'passage observed'} at played minute ${r.at}.`));}
  if(v.objectHere)body.append(n('p','The observed waterlogged object is physically here. Shifting it moves the same object; it does not create a carried copy.'));
  if(v.plateBody)body.append(n('p','Your own weight depresses the observed floor lever. Walking away releases that weight; an object, fitted support, tied line or someone actually remaining there can keep its effect.'));
  if(v.gateKnown)body.append(n('p',`The observed lifting mechanism is ${v.gate?'held':'not held'}. Installed supports, tied rope and actual weight keep their distinct custody.`));
  if(v.remaining!==null)body.append(n('p',v.cleared?'The observed working face is exhausted. Its changed condition and installed support remain.':`${v.remaining} visible mineral chunks remain in this face.`));
  if(v.room!==null)body.append(n('p',`Attended local flow observations ${v.observedMinutes} minutes; ${v.lesson?'handling lesson learned':'one real observation may teach it; thirty attended minutes establish it'}. Field-failure learning ${v.fieldLearning}; this combines with your actual trial learning for later search and tempering control.`));
  for(const row of v.actions){const b=n('button',row.label),q=row.quote;b.type='button';b.dataset.drainageAction=JSON.stringify({id:row.id,...(row.to!==undefined?{to:row.to}:{}),...(row.approach?{approach:row.approach,kit:row.kit}:{})});b.disabled=!q.eligible;b.title=q.reason||'';b.onclick=()=>{try{act(JSON.parse(b.dataset.drainageAction));notice.textContent='The actual site work is recorded.';}catch(e){notice.textContent=e.message;}render();};const wrap=n('div');wrap.append(b);if(row.id==='search'&&q.eligible)wrap.append(n('p',`${q.minutes} min, ${q.stamina} stamina, ${q.spend.find(r=>r.key.includes('Charcoal'))?.count||0} charcoal${row.kit?' and one survey kit':''}; ${q.risk}% fumble risk, up to ${q.reward} actual ore if successful. The next face changes after either outcome.`));else if(row.id==='push'&&q.eligible)wrap.append(n('p',`${q.minutes} played minutes and ${q.stamina} stamina at your actual strength.`));else if(!q.eligible)wrap.append(n('small',q.reason));body.append(wrap);}
 };
 definePanel({id:'drainage-site',title:'Riverside exploration',role:'actions',node:root,home:document.getElementById('main_content'),defaultDock:'center',discovered:()=>read().visible,eligible:()=>read().visible});render();return {render};
}
