import {hpCalendarBinding} from './book_world_hp_facts.js';
import {check as assert, natural} from './basics.js';
import {WORLD_CALENDAR_PROFILES, WORLD_DAY_EVENTS} from './world_calendar_content.js';
import {legacyClimateEnvironment} from './world_climate.js';
import {MOL_START_ZORIAN} from './book_world_mol_starts.js';
const pad = n => String(n).padStart(2, '0');
const seasons = ['Spring', 'Summer', 'Autumn', 'Winter'];

// Fixed arithmetic only in this legacy slice. Unsupported algorithms fail closed.
export function projectCalendar(profile, {elapsed = 0, unit = 'played_minutes', instanceId, calendar = null}) {
    assert(profile?.algorithmId === 'fixed_months' && profile.algorithmRevision === 1 &&
        Number.isSafeInteger(profile.revision) && profile.revision > 0 && typeof profile.id === 'string', 'Unavailable calendar profile.');
    const u = profile.units, months = profile.months, a = calendar ?? profile.anchor;
    assert(u && natural(u.minutesPerHour) && u.minutesPerHour > 0 && natural(u.hoursPerDay) && u.hoursPerDay > 0 &&
        Array.isArray(months) && months.length > 0 && months.every(m => natural(m.days) && m.days > 0), 'Invalid calendar units.');
    assert(unit === 'played_minutes' && natural(elapsed) && typeof instanceId === 'string' && instanceId.length > 0, 'Invalid calendar coordinate.');
    assert(a && natural(a.year) && a.year > 0 && natural(a.month) && a.month > 0 && a.month <= months.length &&
        natural(a.day) && a.day > 0 && a.day <= months[a.month - 1].days && natural(a.hour) && a.hour < u.hoursPerDay &&
        natural(a.minute) && a.minute < u.minutesPerHour && natural(a.day_count), 'Invalid calendar anchor.');
    const dayLength = u.minutesPerHour * u.hoursPerDay, yearLength = months.reduce((n, m) => n + m.days, 0);
    const anchorDay = (a.year - 1) * yearLength + months.slice(0, a.month - 1).reduce((n, m) => n + m.days, 0) + a.day - 1;
    const total = anchorDay * dayLength + a.hour * u.minutesPerHour + a.minute + elapsed;
    assert(Number.isSafeInteger(dayLength) && Number.isSafeInteger(yearLength) && Number.isSafeInteger(total), 'Calendar overflow.');
    const absoluteLocalDay = Math.floor(total / dayLength), minuteWithinDay = total % dayLength;
    const day_count = a.day_count + absoluteLocalDay - anchorDay;
    assert(natural(day_count), 'Calendar weekday overflow.');
    const year = Math.floor(absoluteLocalDay / yearLength) + 1;
    let remaining = absoluteLocalDay % yearLength, month = 1;
    while (remaining >= months[month - 1].days) {remaining -= months[month - 1].days; month++;}
    const hour = Math.floor(minuteWithinDay / u.minutesPerHour), minute = minuteWithinDay % u.minutesPerHour;
    const seasonId = profile.seasons ? seasons[Math.floor((month - 1) / 3)] : null;
    // Public projection uses only declared date fields; no event graph or hidden overlay enters it.
    return {profileId: profile.id, profileRevision: profile.revision, instanceId,
        dayIdentity: JSON.stringify([instanceId, profile.id, profile.revision, absoluteLocalDay]),
        absoluteLocalDay, minuteWithinDay, dayFraction: minuteWithinDay / dayLength,
        year, month, day: remaining + 1, hour, minute, day_count,
        weekday: profile.week?.[day_count % profile.week.length] ?? null, showWeekday: profile.showWeekday === true,
        seasonId, precision: profile.precision, label: profile.label, format: profile.format,
        description: profile.format === 'elapsed' ? 'Local elapsed shift date; civil calendar unknown.' : 'Authored legacy numeric calendar; not a sourced civil date.'};
}
export function formatCalendar(view, {time = false} = {}) {
    if (!view) return 'Local date unavailable';
    // An elapsed profile may opt in to a named weekday and plain day count (the book gives order and weekday, not a date).
    const date = view.format === 'elapsed' && view.showWeekday && view.weekday ? `${view.weekday}, day ${view.absoluteLocalDay + 1}` :
        view.format === 'elapsed' ? `Day ${view.absoluteLocalDay + 1} here (calendar date not known)` :
        `${pad(view.day)}/${pad(view.month)}/${view.year}`;
    return date + (time ? ` ${pad(view.hour)}:${pad(view.minute)}` : '') +
        (view.seasonId ? `, ${view.seasonId}, ${view.weekday}` : '');
}
export function calendarEnvironment(view) {
    // Preserve legacy 20:00 physical light; descriptive Night remains 21:00.
    const daylight = legacyClimateEnvironment({...view, month: 1, hour: Math.floor(view.dayFraction * 24),
        minute: Math.round(view.dayFraction * 1440) % 60}).daylight;
    return {absoluteLocalDay: view.day_count, dayFraction: view.dayFraction,
        seasonId: view.seasonId, seasonPhase: null, daylight};
}
// One visitor binding for display and process/source readers. No home fallback.
function visitorCalendarBinding(state) {
    const worldId = state?.actors?.player?.worldId, profile = WORLD_CALENDAR_PROFILES[worldId];
    if (!profile || worldId === 'base.frontier') return null;
    const domain = worldId === 'book.mol.cyoria' ? state.motherOfLearning : state.bookWorldCampaign;
    const visit = domain?.visits?.find(v => v.id === domain.activeVisitId && v.status === 'active');
    let instance = domain?.instances?.find(i => i.id === visit?.instanceId && i.worldId === worldId);
    // The Zorian seat lives in the world with no visit record: its run clock is the expansion clock since the run began
    // (`runStartedAt`, else the start's own `initializedAt`), so no second clock and no visit invented.
    if (!visit && worldId === 'book.mol.cyoria' && domain?.entryProfile === MOL_START_ZORIAN && natural(state.clock)) {
        const base = domain.instances?.find(i => i.worldId === worldId);
        const since = state.clock - (domain.runStartedAt ?? domain.initializedAt);
        if (base && natural(since)) instance = {...base, clock: {...base.clock, elapsed: since}};
    }
    if (!instance || domain.definitionRevision !== 1 || instance.definitionId !== profile.definitionId ||
        instance.definitionRevision !== profile.definitionRevision) return null;
    return {worldId, profile, instance};
}
export function resolveWorldCalendar(state, homeCalendar) {
    const worldId = state?.actors?.player?.worldId ?? 'base.frontier';
    const hp=hpCalendarBinding(state);
    if(hp)return projectCalendar(hp.profile,{instanceId:hp.instanceId,elapsed:hp.elapsed,unit:'played_minutes'});
    if (worldId === 'base.frontier') return projectCalendar(WORLD_CALENDAR_PROFILES[worldId], {instanceId: 'frontier.main', calendar: homeCalendar});
    const binding = visitorCalendarBinding(state);
    return binding ? projectCalendar(binding.profile, {instanceId: binding.instance.id,
        elapsed: binding.instance.clock.elapsed, unit: binding.instance.clock.unit}) : null;
}
// Pure source coordinate from a supported active visitor, including history.
// `at` is owning local elapsed time, never an anchored calendar day or root clock.
// Other clocks keep their own adapters until an actual source adopts them.
export function sourceCalendarAt(state, at) {
    const binding = visitorCalendarBinding(state);
    if (!binding) return null;
    const {worldId, profile, instance} = binding, clock = instance.clock;
    if (!clock || clock.unit !== 'played_minutes' || clock.absence !== 'freeze' || !natural(clock.elapsed)) return null;
    if (at === undefined) at = clock.elapsed;
    assert(natural(at) && at <= clock.elapsed, 'Source calendar requires a retained local coordinate, not future or foreign time.');
    const view = projectCalendar(profile, {instanceId: instance.id, elapsed: at, unit: clock.unit});
    return {worldId, instanceId: instance.id, profileId: view.profileId, profileRevision: view.profileRevision,
        at, minuteWithinDay: view.minuteWithinDay, seasonId: view.seasonId,
        minutesPerHour: profile.units.minutesPerHour, hoursPerDay: profile.units.hoursPerDay};
}
// Session-only cursor. Invoke after successful publication, never from render.
export function createCalendarLog(emit) {
    let previous = null;
    return {
        reset() {previous = null;},
        commit(view) {
            if (!view) {previous = null; return false;}
            if (previous?.dayIdentity === view.dayIdentity) return false;
            const sameBinding = previous?.instanceId === view.instanceId && previous?.profileId === view.profileId && previous?.profileRevision === view.profileRevision;
            const skipped = sameBinding ? Math.max(0, view.absoluteLocalDay - previous.absoluteLocalDay - 1) : 0;
            const text = `[ ${view.label} · ${formatCalendar(view)} ]` +
                (skipped ? ` (${skipped} intervening local ${skipped === 1 ? 'day' : 'days'} skipped; ${formatCalendar(previous)} → ${formatCalendar(view)})` : '');
            emit(text, 'notification', {safeText: true, calendarDate: view.dayIdentity, description: view.description});
            previous = view;
            return true;
        },
    };
}

// G6: dated events for one profile, shown on their day and never before. Reuses the projected view; no second clock.
const LOCATOR = /^en b\d+ c\d+ p\d+$/;
export function validateDayEvents(content, profile) {
    const errors = [], seen = new Set(), months = profile.months;
    if (content?.profileId !== profile.id || !Array.isArray(content.events)) return ['Day events do not match the calendar profile.'];
    for (const e of content.events) {
        if (typeof e.id !== 'string' || seen.has(e.id)) errors.push(`${e.id}: id`);
        seen.add(e.id);
        if (!['stated', 'inferred', 'fixture', 'unknown'].includes(e.dateBasis)) errors.push(`${e.id}: dateBasis`);
        if (e.dateBasis === 'unknown') {
            if (e.day != null || e.hour != null) errors.push(`${e.id}: unknown date carries a day`);
            continue;
        }
        const m = months[(e.month ?? 1) - 1];
        if (!m || !natural(e.day) || e.day < 1 || e.day > m.days || (e.hour != null && !(natural(e.hour) && e.hour < profile.units.hoursPerDay))) errors.push(`${e.id}: date`);
        if (e.dateBasis !== 'fixture' && !LOCATOR.test(e.locator ?? '')) errors.push(`${e.id}: source locator`);
    }
    return errors;
}
export function dayEventsDue(profile, view, content) {
    if (!content || !view) return [];
    const u = profile.units, dayLength = u.minutesPerHour * u.hoursPerDay, now = view.absoluteLocalDay * dayLength + view.minuteWithinDay;
    return content.events.filter(e => e.dateBasis !== 'unknown' && e.day != null).map(e => {
        const before = profile.months.slice(0, (e.month ?? 1) - 1).reduce((n, m) => n + m.days, 0);
        const at = ((e.year ?? 1) - 1) * profile.months.reduce((n, m) => n + m.days, 0) * dayLength + (before + e.day - 1) * dayLength + (e.hour ?? 0) * u.minutesPerHour;
        return {...e, ageMinutes: now - at};
    }).filter(e => e.ageMinutes >= 0).sort((a, b) => a.ageMinutes - b.ageMinutes || a.id.localeCompare(b.id));
}
// News rows for the active visitor world; worlds without authored day events return nothing.
export function worldDayNews(state) {
    const worldId = state?.actors?.player?.worldId, content = WORLD_DAY_EVENTS[worldId];
    if (!content) return [];
    const view = resolveWorldCalendar(state, null);
    if (!view) return [];
    return dayEventsDue(WORLD_CALENDAR_PROFILES[worldId], view, content).map(e => {
        const hh = e.hour == null ? '' : `, ${pad(e.hour)}:00`;
        return {id: `calendar:${e.id}`, ageMinutes: e.ageMinutes, dateBasis: e.dateBasis, locator: e.locator,
            text: `Day ${e.day}${hh}: ${e.text}${e.dateBasis === 'inferred' ? ' (date inferred from the text)' : ''}`};
    });
}
