import {MIXTURE_ID,getMixtureOwner,productFromKey} from '../mixture_state.js';
"use strict";

// The catalog binds these operations once it has registered its templates.
// Inventory storage must not import the catalog and its native UI/bootstrap graph.
let itemOperations;
export function configureInventoryItems(operations) {
    if(typeof operations?.fromKey!=='function'||typeof operations?.keyFromTemplate!=='function')throw new TypeError('Invalid inventory item operations.');
    itemOperations=Object.freeze({...operations});
}
function inventoryItems() {
    if(!itemOperations)throw new Error('Inventory item catalog is not configured.');
    return itemOperations;
}
import { publishChange } from "../ui_change_signal.js";

import {inventories} from "../data/component_references.js";

//extended by Trader and Person (with Person having up to two Inventories, one directly and one via Trader component)
class InventoryComponent {
    
    #items = {};

    getItems() {
        return this.#items;
    }

    /**
     * @description adds items from the list to inventory; don't use this method directly, there are other methods that call this one and take care of display
     * @param {Array} items - [{item_key, count, item_id (if no key), quality (optional if no key)},...]
     */
    addToInventory(items) {
        let anything_new = false;
        
        for(let i = 0; i < items.length; i++){
            let item_key;
            if(items[i].item_key){
                item_key = items[i].item_key;
            } else {
                item_key = inventoryItems().keyFromTemplate(items[i].item_id,items[i].quality);
            } 

            if(item_key.startsWith('{')&&JSON.parse(item_key).id===MIXTURE_ID){productFromKey(getMixtureOwner(),item_key);if(items[i].count!==undefined&&(!Number.isSafeInteger(items[i].count)||items[i].count<1))throw new TypeError('Generated vials need positive whole counts.');}
            if(!(item_key in this.#items)) {//not in inventory
                if(!items[i].count) {
                    items[i].count = 1;
                }
                const item = inventoryItems().fromKey(item_key);
                this.#items[item_key] = {item, count: items[i].count};
                anything_new = true;
            } else { //in inventory
                if(items[i].count === undefined) {
                    this.#items[item_key].count += 1;
                } else if(typeof items[i].count === "number" && !isNaN(items[i].count)){
                    this.#items[item_key].count += items[i].count;
                } else {
                    throw new TypeError(`Tried to add "${items[i].count}" items, which is not a valid number!`);
                }
            }
        }
        if(items.length) publishChange("inventory", "inventory"); //UIX2: observers re-read; publishes no state
        return anything_new;
    }

    /**
     * @description removes specified items (array of {item_key, count}) from the inventory; don't use this method directly, there are other methods that call this one and take care of display
     * @param {Array} items [{item_key, item_count}]
     **/
    removeFromInventory(items) {
        for(let i = 0; i < items.length; i++){       
            if(items[i].item_key in this.#items) { //check if its in inventory, just in case, probably not needed

                if(typeof items[i].item_count === "number" && Number.isInteger(items[i].item_count) && items[i].item_count >= 1)  {
                    this.#items[items[i].item_key].count -= items[i].item_count;
                }  else {
                    this.#items[items[i].item_key].count -= 1; //remove one if count was not passed
                }
    
                if(this.#items[items[i].item_key].count == 0) {
                    delete this.#items[items[i].item_key]; 
                    //removes item from inventory if it's county is 0
                } else if(this.#items[items[i].item_key].count < 0 || isNaN(this.#items[items[i].item_key].count)) {
                    throw new Error(`Item count for key "${items[i].item_key}" reached an illegal value of "${this.#items[items[i].item_key].count}"`);
                }
                
            } else { 
                throw new Error("Tried to remove item that was not present in inventory");
            }
        }
        if(items.length) publishChange("inventory", "inventory");
    }

    emptyInventory() {
        this.#items = {};
        publishChange("inventory", "inventory");
    }
}

export default InventoryComponent;
export { inventories };
