function accept_trade() {
    if(restockReview) {
        restockReview=false;calculate_total_values();
        throw new Error('The shop restocked. Review the updated selection and prices, then accept again.');
    }
    if(!current_trader || !to_buy.items.length && !to_sell.items.length) return;
    const quoted = current_quote;
    calculate_total_values();
    // Repricing is read-only. Keep selections and the new quote on a stale or
    // failed command so the player can review and retry it.
    if(!quoted || tradeQuoteFingerprint(quoted) !== tradeQuoteFingerprint(current_quote)) {
        update_displayed_total_price(to_sell.value - current_quote.marketLife.quote.total);
        throw new Error("Trade quote changed. Review the refreshed price before accepting again.");
    }
    host.commitNativeTrade(quoted, current_quote);
    const region=current_location.market_region;
    const top=[...quoted.buy].sort((a,b)=>get_item_value(b)-get_item_value(a))[0];
    recordTrade({region,vendorId:quoted.vendorId,sellValue:quoted.sellValue,buyValue:quoted.buyValue,bought:top?getItemFromKey(top.item_key).name:null,
        seen:[...quoted.sell,...quoted.buy].map(({item_key})=>{const item=getItemFromKey(item_key);
            return {key:item_key,label:item.name||item_key,price:regionalUnit(item,'sell')??item.getValue({region})};})});
    cancel_trade();
    update_displayed_money();
}

