// Stable presentation home: settlement totals stay visible while optional
// coupon/standing explanations open in one disclosure. No quote is recomputed.
function tradeQuoteDetails(anchor) {
    const existing=document.getElementById('trade_quote_details');if(existing)return existing;
    const details=document.createElement('details');details.id='trade_quote_details';const title=document.createElement('summary');title.textContent='Price details and coupon';details.append(title);anchor.after(details);
    return details;
}
function renderP23MarketQuote() {
    const preview=current_quote?.marketLife,context=preview?.context;
    const eligible=current_trader==='villageTrader'&&context?.worldId==='base.frontier'&&context.location==='Village';
    if(!eligible){document.getElementById('p23_market_trade_quote')?.remove();return;}
    const total=document.getElementById('trade_price_value');if(!total)return;
    let box=document.getElementById('p23_market_trade_quote');
    if(!box){box=document.createElement('div');box.id='p23_market_trade_quote';tradeQuoteDetails(total).append(box);}
    box.replaceChildren();
    const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=use_market_coupon;
    input.dataset.p23MarketCoupon='true';input.disabled=preview.state.couponsIssued<=preview.state.couponsUsed;
    label.append(input,document.createTextNode(' Use one earned customer coupon (up to 5 coins; minimum payment 1 coin)'));
    input.onchange=()=>{use_market_coupon=input.checked;const net=calculate_total_values();update_displayed_total_price(net);};
    const explanation=document.createElement('p');explanation.textContent=preview.quote.explanation;box.append(label,explanation);
}

function renderStandingBox() {
    const anchor=document.getElementById('trade_price_value');if(!anchor)return;
    let box=document.getElementById('economy_standing_terms');
    if(!box){box=document.createElement('div');box.id='economy_standing_terms';box.setAttribute('role','group');tradeQuoteDetails(anchor).append(box);}
    renderStandingTerms(box,current_terms);renderTalkBox(box);
}

function get_item_value(selected_item) {
    const profit_margin = NPCRegistry.get(current_trader).getTraderComponent().getProfitMargin(current_location.market_region);

    const item = getItemFromKey(selected_item.item_key);

    const regional = regionalLine(item, 'buy', selected_item.count);
    if(regional !== null) return regional;
    return round_item_price(profit_margin * item.getValue({quality: item.quality, region: current_location.market_region})) * selected_item.count;
}

/**
 * sorts by tier, then by value, in descending order
 * */
function sort_traded_items(a,b) {
    const item_a = getItemFromKey(a.item_key);
    const item_b = getItemFromKey(b.item_key);
    const tier_a = item_a.getMarketSaturationGroup().group_tier;
    const tier_b = item_b.getMarketSaturationGroup().group_tier;
    if(tier_a != tier_b) {
        return tier_b - tier_a;
    } else {
        return item_b.getBaseValue() - item_a.getBaseValue();
    }
}

// ECC43: the keeper's opening line, read from what they remember, today's haggle, the stall and price causes.
// A keyed pick on (save root, vendor, day, visits): reopening the stall the same day repeats the line.
export function greetingFacts(trader_key, context) {
    const npc=NPCRegistry.get(trader_key), trader=npc.getTraderComponent(), memory=shopMemory(trader_key), today=current_game_time.day_count;
    const onShelf=new Set(Object.values(npc.getTraderInventory()).filter(e=>e?.count>0).map(e=>e.item?.name));
    const gone=trader.stapleNames(context).map(name=>item_templates[name]?.name ?? name).find(name=>trader.laid_out?.has(name)&&!onShelf.has(name));
    const restockIn=trader.daysToRestock();
    const terms=termsFor(current_location.market_region,trader_key,character.reputation);
    return {visits:memory.visits,today,lastBought:memory.lastBought,boughtDay:memory.boughtDay,talked:talks.get(`${trader_key}:${today}`)??null,
        soldOut:gone&&restockIn?{item:gone,restockIn}:null,
        shortage:terms.parts.some(p=>p.cause==='shortage')};
}
function sayGreeting(trader_key, context) {
    const line=document.getElementById('trade_greeting');if(!line)return;
    const facts=greetingFacts(trader_key, context);
    const root=gamePeekRoot();
    const pick=(kind,size)=>indexFromU32(drawU32(root,address('shop-greeting',trader_key,facts.today,facts.visits,kind)),size);
    const {text,why}=shopGreeting({vendorId:trader_key,facts,pick});
    const npc=NPCRegistry.get(trader_key),who=String(npc.getName?.()??npc.name??'').split(',')[0].trim();
    const name=document.createElement('strong');name.textContent=who;
    line.replaceChildren(name,document.createTextNode(`: \u201c${text}\u201d`));line.dataset.greetingWhy=why.join(' ');line.hidden=false;
}

/** Short reason in the trade view's own status line; a pending restock review keeps its longer text. */
export function sayTradeReason(text='') {
    if(restockReview) return;
    const notice=document.getElementById('trade_stock_notice');
    if(notice){notice.hidden=!text;if(notice.textContent!==text)notice.textContent=text;}
}
function setRestockNotice(text='') {
    const notice=document.getElementById('trade_stock_notice');
    if(notice){notice.hidden=!text;notice.textContent=text;}
}
// The existing native clock calls this domain. NPC/TraderComponent remains the
// stock, calendar, seeded generation and save owner; projections do not restock.
export function refreshOpenShop() {
    if(!current_trader || !host.get_context) return false;
    const npc=NPCRegistry.get(current_trader), trader=npc.getTraderComponent();
    if(trader.played_minute_refresh || !trader.can_refresh()) return false;
    const buy=to_buy.items.map(row=>({...row})),sell=to_sell.items.map(row=>({...row})),coupon=use_market_coupon;
    if(!trader.refresh(host.get_context())) return false;
    const recoveredBuy=recoverTradeRequests(buy,npc.getTraderInventory());
    const recoveredSell=recoverTradeRequests(sell,character.getItems());
    cancel_trade();use_market_coupon=coupon;
    for(const row of recoveredBuy)add_to_buying_list(row);
    for(const row of recoveredSell)add_to_selling_list(row);
    calculate_total_values();restockReview=buy.length>0 || sell.length>0;
    update_displayed_character_inventory({is_trade:true});update_displayed_trader_inventory();
    setRestockNotice('The shop restocked. Available selections were kept, with quantities reduced to current stock where needed. Review the updated selection and prices before accepting.');
    return true;
}
registerDomain({id:'native-shop-restock',tick:refreshOpenShop});

