// LTU7 / RPX16 fight situation card: fight state in, figure spec and scene in. Leaf module: no DOM,
// no game state. It reads only the observer-safe opponent board (opponent_board.js) and the
// controlled actor's own exact numbers (AD8), so nothing here can show a fact the board hides.
// What it will not claim, by design (docs/representations/COMBAT.md):
//   - chances only one on one; with several opponents the native view gives ratings, not chances (UR40)
//   - intent is unassessed until an appraisal source exists (CBR14, LSD294); never guessed from speed
//   - the lethal line is a stated bound: hardest ordinary blow after your defense, before crits, armor
//     piercing or element, which the opponent's hidden stats can add (LSD384)
//   - the ring is who is in the fight, not distance; native combat has no range data
import {letterFor, factShown, knowledgeOf} from '../opponent_board.js';
import {mitigateCombatDamage, scaleByType} from '../combat_math.js';
import {damageTypeLabel, mixText} from '../damage_types.js';

// The native roll is power x (0.8..1.2), rounded to a tenth, per strike (combat_math.rollBaseCombatDamage).
const HARDEST_ROLL = 1.2;
export function chanceWord(pct) {
    if (pct >= 95) return 'almost always';
    if (pct >= 75) return 'usually';
    if (pct >= 55) return 'more often than not';
    if (pct >= 45) return 'about half the time';
    if (pct >= 25) return 'sometimes';
    if (pct >= 6) return 'rarely';
    return 'almost never';
}
const factOf = (opp, label) => (opp.facts || []).find(f => f.label === label && factShown(f)) || null;
const pctOf = fact => fact ? Number(/(\d+(?:\.\d+)?)%/.exec(String(fact.value))?.[1]) : NaN;
const perSecond = fact => fact ? Number(/(\d+(?:\.\d+)?)/.exec(String(fact.value))?.[1]) : NaN;
// "12 dmg x2" -> {power: 12, count: 2}; null when the attack is not a shown fact.
export function attackOf(opp) {
    const fact = factOf(opp, 'Attack'), m = fact && /(\d+(?:\.\d+)?)\s*dmg(?:\s*x(\d+))?/.exec(String(fact.value));
    return m ? {power: Number(m[1]), count: m[2] ? Number(m[2]) : 1, typeMultiplier: Number.isFinite(fact.typeMultiplier) ? fact.typeMultiplier : 1} : null;
}
// Hardest ordinary blow after your own defense layers. Native enemy strikes use damage modifier 1;
// crits, the attacker's armor piercing and elemental or pledge modifiers are excluded and the text says so.
// The enemy's attack mix against your worn per-type protection is included (damage_types.js, CBD10): a weakness can raise the bound.
export function hardestBlow(attack, you = {}) {
    if (!attack) return null;
    const one = Math.round(10 * HARDEST_ROLL * attack.power) / 10;
    return scaleByType(mitigateCombatDamage(Array(attack.count).fill(one), you.defense || 0, {floorShare: you.minDamageShare ?? .05, taken: you.damageTaken ?? 1}), attack.typeMultiplier ?? 1);
}
// The native leave choice in a fight: the leave branch (travel_normal, "Go back to" or the place's
// leave text), never Quick return. Safe only because display.js skips onward links while is_combat,
// so in a fight the travel list is the leave branch plus Quick return; the card shows only in a fight.
export function pickLeaveChoice(choices = []) {
    return choices.find(n => n.classList?.contains('travel_normal') && !/^\s*Quick return/i.test(n.textContent || '')) || null;
}
const fmt = n => Number.isInteger(n) ? String(n) : n.toFixed(1);
const nameOf = (opp, kin) => kin > 1 ? `${opp.name} ${opp.letter}` : opp.name;

/**
 * board: fromCombatOpponentsProjection(...) or projectNativeOpponents(...) shape.
 * you:   {name, health: {current, max}, speed, defense, minDamageShare, damageTaken, sideSize}
 *        own exact numbers; sideSize is how many fighters stand on your side (allies change targeting).
 * place: words for the header.
 * Returns {active, spec, odds, lethal, tempo, intent, summary, versus}; spec is a figure spec (src/ui/figure.js),
 * versus is the versus-row model drawn by src/ui/combat_versus.js.
 */
export function fightSituation(board, you = {}, {place = ''} = {}) {
    const opponents = board?.opponents || [];
    if (!opponents.length) return {active: false, spec: null, odds: null, lethal: [], tempo: null, summary: 'No fight right now.'};
    const kin = new Map(); for (const o of opponents) kin.set(o.name, (kin.get(o.name) || 0) + 1);
    const label = o => nameOf({...o, letter: o.letter || letterFor(o.slot ?? 0)}, kin.get(o.name));
    const standing = opponents.filter(o => !o.defeated), hp = you.health || {}, alone = (you.sideSize ?? 1) <= 1;

    // Odds in words, one on one only.
    let odds;
    if (standing.length === 1 && opponents.length === 1) {
        const o = standing[0], yours = pctOf(factOf(o, 'You hit them')), theirs = pctOf(factOf(o, 'Hit you')), evade = pctOf(factOf(o, 'Evade you'));
        const parts = [];
        if (Number.isFinite(yours)) parts.push(`you hit ${chanceWord(yours)} (${fmt(yours)}%)`);
        if (Number.isFinite(theirs)) parts.push(`${label(o)} hits you ${chanceWord(theirs)} (${fmt(theirs)}%)`);
        else if (Number.isFinite(evade)) parts.push(`${label(o)} evades you ${chanceWord(evade)} (${fmt(evade)}%)`);
        odds = parts.length ? {shown: true, text: `Odds: ${parts.join('; ')}.`, you: Number.isFinite(yours) ? yours : null, them: Number.isFinite(theirs) ? theirs : null} : {shown: false, text: 'Odds: you have not sized this opponent up yet.'};
    } else {
        odds = {shown: false, text: `Odds: no hit chances in a fight with ${opponents.length} opponents, only attack and evasion ratings, which are not chances.`};
    }

    // Lethal telegraph: a stated bound from shown attack and your exact health and defense.
    const lethal = [];
    let combined = 0, combinedKnown = true;
    for (const o of standing) {
        const blow = hardestBlow(attackOf(o), you);
        if (blow === null) { combinedKnown = false; continue; }
        combined += blow;
        if (Number.isFinite(hp.current) && blow >= hp.current) lethal.push({id: o.id, level: 'lethal', blow, text: `Could down you: ${label(o)}'s hardest normal hit takes up to ${fmt(blow)} hp after your defense, and you have ${fmt(hp.current)}. Crits, armor piercing or elements can add more.`});
        else if (Number.isFinite(hp.current) && blow * 2 >= hp.current) lethal.push({id: o.id, level: 'heavy', blow, text: `Heavy: ${label(o)}'s hardest normal hit takes up to ${fmt(blow)} of your ${fmt(hp.current)} hp. Crits, armor piercing or elements can add more.`});
    }
    // Together: only shown attacks count; an unassessed opponent makes it a lower bound.
    if (standing.length > 1 && combined > 0 && Number.isFinite(hp.current) && combined >= hp.current && !lethal.some(l => l.level === 'lethal'))
        lethal.push({id: null, level: 'lethal', text: `Could down you together: if ${combinedKnown ? `all ${standing.length}` : 'the ones you have sized up'} land their hardest normal hits before you recover, that is ${combinedKnown ? '' : 'at least '}${fmt(combined)} hp against your ${fmt(hp.current)}.`});

    // Text-first tempo: shown speeds against yours.
    const speeds = standing.map(o => ({o, s: perSecond(factOf(o, 'Speed'))})).filter(x => Number.isFinite(x.s) && x.s > 0);
    let tempo;
    if (Number.isFinite(you.speed) && you.speed > 0 && speeds.length) {
        const fastest = speeds.reduce((a, b) => b.s > a.s ? b : a), ratio = fastest.s / you.speed;
        tempo = ratio >= 1.15 ? `Tempo: ${label(fastest.o)} strikes about ${fmt(Math.round(ratio * 10) / 10)} times for each of your blows.`
            : ratio <= 1 / 1.15 ? `Tempo: you strike about ${fmt(Math.round(10 / ratio) / 10)} times for each of ${label(fastest.o)}'s blows.`
            : `Tempo: you and ${label(fastest.o)} strike at about the same pace.`;
    } else tempo = 'Tempo: you have not sized up their pace yet.';
    const intent = 'Intent: you cannot read what they will do next yet (unassessed).';

    const lethalIds = new Set(lethal.filter(l => l.level === 'lethal').map(l => l.id));
    const ring = {id: 'fight', label: 'In this fight', radius: .82, count: opponents.length};
    const nodes = [{id: 'you', label: `${you.name || 'You'} ${Number.isFinite(hp.current) ? `${fmt(hp.current)}/${fmt(hp.max)} hp` : ''}`.trim(), glyph: 'Y', at: 'center', state: 'active'}];
    const edges = [];
    opponents.forEach((o, i) => {
        const known = knowledgeOf(o), state = o.defeated ? 'broken' : known === 'unknown' ? 'unknown' : lethalIds.has(o.id) ? 'strained' : undefined;
        const health = o.defeated ? 'down' : o.health && factShown({knowledge: o.health.knowledge, value: o.health.text}) ? o.health.text : '??? hp';
        nodes.push({id: `opp-${i}`, label: `${label(o)} · ${health}`, glyph: o.letter || letterFor(o.slot ?? i), ring: 'fight', index: i, ...(state ? {state} : {}), ...(state === 'strained' ? {effect: 'pulse'} : {})});
        if (!o.defeated) edges.push(alone ? {from: `opp-${i}`, to: 'you', kind: 'strikes'} : {from: `opp-${i}`, to: 'you', kind: 'strikes', label: 'target unread', state: 'unknown'});
    });
    const summary = `${place ? `${place}: ` : ''}${standing.length} of ${opponents.length} opponent${opponents.length === 1 ? '' : 's'} standing${Number.isFinite(hp.current) ? `; you have ${fmt(hp.current)} of ${fmt(hp.max)} hp` : ''}.`;
    const spec = {
        id: 'fight-situation', size: opponents.length > 2 ? 560 : 380, title: 'Fight situation', summary,
        rings: [ring], nodes, edges,
        notes: [
            // Only a lethal line carries the could-down-you mark; a heavy blow cannot down you by itself.
            ...lethal.map(l => l.level === 'lethal' ? {state: 'strained', text: l.text} : {text: l.text}),
            {state: odds.shown ? 'active' : 'unknown', text: odds.text},
            {text: tempo},
            {state: 'unknown', text: intent},
        ],
        legend: [
            {state: 'active', label: 'you'}, {state: 'strained', label: 'could down you'}, {state: 'broken', label: 'down'},
            {state: 'unknown', label: 'not assessed'}, {kind: 'strikes', label: 'who strikes whom'},
        ],
    };
    // Versus row (round 2 default): your side, then one card per opponent with derived chips only.
    // Raw stats stay in the Opponent panel; these are readings. Roles, not looks (round 13 motifs).
    const byId = new Map(lethal.filter(l => l.id).map(l => [l.id, l]));
    const versus = {
        you: {name: you.name || 'You', hp: Number.isFinite(hp.current) ? {current: hp.current, max: hp.max, text: `${fmt(hp.current)}/${fmt(hp.max)} hp`} : null, allies: Math.max(0, (you.sideSize ?? 1) - 1)},
        together: lethal.find(l => l.id === null) || null,
        opponents: opponents.map(o => {
            const known = knowledgeOf(o), seen = o.health && factShown({knowledge: o.health.knowledge, value: o.health.text}), l = byId.get(o.id);
            const threat = o.defeated ? {level: 'down', word: 'Down'} : known === 'unknown' || !attackOf(o) ? {level: 'unknown', word: 'Not sized up'}
                : l ? {level: l.level, word: l.level === 'lethal' ? 'Could down you' : 'Heavy', blow: l.blow} : {level: 'light', word: 'Light'};
            const duel = odds.shown && opponents.length === 1;
            return {id: o.id, letter: o.letter || letterFor(o.slot ?? 0), name: label(o), down: !!o.defeated, known,
                hp: o.defeated ? {text: 'Down', fraction: 0} : seen ? {text: o.health.text, fraction: o.health.progress == null ? null : o.health.progress / 100} : {text: '??? hp', fraction: null},
                threat, intent: o.defeated ? null : {known: false, word: 'Intent unread'},
                odds: duel && !o.defeated ? {you: odds.you, them: odds.them, youWord: odds.you == null ? null : chanceWord(odds.you), themWord: odds.them == null ? null : chanceWord(odds.them)} : null,
                target: o.defeated ? null : alone ? 'you' : 'unread'};
        }),
    };
    return {active: true, spec, odds, lethal, tempo, intent, summary, versus};
}

// Chase as stages (pursuit.js pursuitView). The pursuit model has stages, not distance, so the
// track has steps; a distance track waits for a world that models range (COMBAT.md, dial D2).
const CHASE_STAGES = [['following', 'Following you'], ['contact', 'Makes contact'], ['encounter', 'Face to face'], ['closed', 'Over']];
export function chaseSituation(view) {
    if (!view) return null;
    const at = CHASE_STAGES.findIndex(([status]) => status === view.status);
    return {
        id: `chase-${view.definitionId}`, size: 460, title: view.label, summary: view.text,
        tracks: [{id: 'stages', label: 'Pursuit', steps: CHASE_STAGES.map(([, label], i) => ({label, state: i < at ? 'done' : i === at ? (view.status === 'closed' ? 'done' : 'current') : 'pending'}))}],
        notes: [{state: 'unknown', text: 'Distance: not modelled here; stages only.'}, ...(view.expiresAt != null ? [{text: `The meeting request lapses at minute ${view.expiresAt}.`}] : [])],
    };
}

// Tempo mode of the one fight surface (COMBAT.md round 3, R3-O1). Input is tempo_fight.js tempoView(b): the
// engine's own knowledge-limited view (hurt words, not hp numbers, for foes). It goes through fightSituation
// so both modes share one versus model; tempo adds damage types (learned per foe, or revealed by a marked
// cheat), the move area and the log. worldId only picks type names and glyphs (AD46); no world ids live here.
const LEARNED_WORD = {resisted: 'resists', 'weak spot': 'weak to', 'no effect': 'unharmed by', normal: 'takes normal'};
export function typeChips(learned = {}, {reveal = null, worldId = null, label = damageTypeLabel} = {}) {
    const rows = Object.entries(learned).map(([type, note]) => ({type, note, source: 'learned'}));
    if (reveal?.defense) for (const [type, m] of Object.entries(reveal.defense)) {
        if (rows.some(r => r.type === type)) continue;
        rows.push({type, note: m === 0 ? 'no effect' : m < 1 ? 'resisted' : m > 1 ? 'weak spot' : 'normal', source: reveal.source || 'cheat'});
    }
    return rows.map(r => {
        const {name, glyph} = label(r.type, worldId);
        return {type: r.type, name, glyph, source: r.source, word: `${LEARNED_WORD[r.note] || r.note} ${name}`};
    });
}
export function tempoSituation(view, {place = '', worldId = null, dev = false} = {}) {
    const f = view?.fight;
    if (!f) return {active: false, mode: 'tempo'};
    const opponents = f.foes.map((o, i) => ({id: o.id, slot: i, letter: letterFor(i), name: o.name, knowledge: 'native', defeated: false,
        health: {text: o.hurt, progress: null, knowledge: 'native'}, facts: []}));
    const me = f.you || {};
    const base = fightSituation({source: 'tempo', opponents}, {name: 'You', health: Number.isFinite(me.hp) ? {current: me.hp, max: me.maxHp} : undefined,
        sideSize: 1 + (f.allies?.length || 0)}, {place});
    if (!base.active) return {active: false, mode: 'tempo', result: f.result || null};
    // Match the native hero's whole-number HP label; the meter still uses the
    // precise health value for its fill and combat calculations.
    if (base.versus.you.hp && Number.isFinite(me.maxHp)) base.versus.you.hp.text = `${Math.ceil(me.hp)}/${Math.ceil(me.maxHp)} hp`;
    const byId = new Map(f.foes.map(o => [o.id, o]));
    for (const o of base.versus.opponents) {
        const foe = byId.get(o.id);
        o.hp = {text: foe.hurt[0].toUpperCase() + foe.hurt.slice(1), fraction: null};
        o.types = typeChips(foe.learned, {reveal: foe.reveal, worldId});
    }
    base.versus.you.mix = me.mix ? mixText(me.mix, worldId) : null;
    if (f.allies?.length) base.versus.you.alliesText = f.allies.map(a => `${a.name} (${a.hurt}${a.order ? `, told: ${a.order}` : ''})`).join(', ');
    const moves = (f.moves || []).map(m => ({...m, mixText: m.mix ? mixText(m.mix, worldId) : ''}));
    const hits = dev ? (f.hits || []).map(h => {
        const slot = h.slot ? ` [${h.slot}]` : '';
        const multiplier = h.multiplier != null ? ` at x${Math.round(h.multiplier * 100) / 100}` : '';
        const split = h.split ? ` (${Object.entries(h.split).map(([t, s]) => `${damageTypeLabel(t, worldId).name} ${Math.round(s * 100)}%`).join(', ')})` : '';
        return `${h.actor} → ${h.target ?? h.foe}${slot}: ${h.dmg ?? h.dealt}${multiplier}${split}`;
    }) : [];
    // One home per fact (DESIGN.md DSG11): hp lives on the versus row, so the summary keeps only who is standing.
    const standing = f.foes.length, summary = `${place ? `${place}: ` : ''}${standing} opponent${standing === 1 ? '' : 's'} standing.`;
    return {active: true, mode: 'tempo', summary, versus: base.versus, next: f.next || [], yourTurn: !!f.yourTurn,
        moves, aims: f.aims || [], aim: f.aim ?? null, orders: f.orders || [], log: [...(f.lines || [])], dev: hits};
}
