export function renderSeedbed({host,view,disabled,act,render,notice}){
 if(!view)return;const text=document.createElement('p');text.textContent=`Conservatory seedbed: ${view.built?'fitted':'not fitted'}. ${view.crop?view.crop.ready?'Ripe crop waits without decay.':`${view.crop.remaining} visited-room minutes to ripen.`:'No crop planted.'} One paid Cloudseed dose grows for 120 minutes on this room’s existing clock. Leaving freezes that room’s time. Collection converts eight minutes of your current technique’s condensate rate, capped at 2.5 by the plant’s size: now ${view.amount/1000} condensate. A full reserve holds the whole crop instead of dropping its yield.`;host.append(text);
 if(view.last){const p=document.createElement('p');p.textContent=`Collected ${view.harvests} crops. Last: ${view.last.amount/1000} condensate at collection-time ${view.last.method} rate ${view.last.rate/1000}/minute.`;host.append(p);}
 for(const [id,label]of [['build','Fit one seedbed · 2 owned rough logs'],['plant','Sow one paid Cloudseed dose'],['harvest',`Collect ripe crop · ${view.amount/1000} condensate at current rate`],['clear','Clear this crop without refund']]){const q=view.quotes[id],b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.mistglassAction='method:seedbed:'+id;b.disabled=disabled||!q.eligible;b.title=q.reason||'';b.onclick=()=>{try{act('method:seedbed:'+id);notice.textContent='';}catch(e){notice.textContent=e.message;}render();};host.append(b);}
}
